/* Mono Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Mono Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 300 50% 100%;
    --foreground: 300 0% 3.55%;
    --card: 300 50% 100%;
    --card-foreground: 300 0% 3.55%;
    --popover: 300 50% 100%;
    --popover-foreground: 300 0% 3.55%;
    --primary: 0 0% 45.61%;
    --primary-foreground: 300 0% 98.68%;
    --secondary: 300 0% 96.06%;
    --secondary-foreground: 0 0% 8.61%;
    --muted: 300 0% 96.06%;
    --muted-foreground: 0 0% 44.47%;
    --accent: 300 0% 96.06%;
    --accent-foreground: 0 0% 8.61%;
    --destructive: 357.18 100% 44.98%;
    --destructive-foreground: 300 0% 96.06%;
    --border: 0 0% 89.56%;
    --input: 0 0% 89.56%;
    --ring: 0 0% 63.26%;
    --chart-1: 0 0% 45.61%;
    --chart-2: 0 0% 45.61%;
    --chart-3: 0 0% 45.61%;
    --chart-4: 0 0% 45.61%;
    --chart-5: 0 0% 45.61%;
    --radius: 0rem;
    --sidebar: 300 0% 98.68%;
    --sidebar-foreground: 300 0% 3.55%;
    --sidebar-primary: 0 0% 8.61%;
    --sidebar-primary-foreground: 300 0% 98.68%;
    --sidebar-accent: 300 0% 96.06%;
    --sidebar-accent-foreground: 0 0% 8.61%;
    --sidebar-border: 0 0% 89.56%;
    --sidebar-ring: 0 0% 63.26%;
    --font-sans: Geist Mono, monospace;
    --font-serif: Geist Mono, monospace;
    --font-mono: Geist Mono, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 1px 0px 0px hsl(0 0% 0% / 0);
    --shadow-xs: 0px 1px 0px 0px hsl(0 0% 0% / 0);
    --shadow-sm:
      0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 1px 2px -1px hsl(0 0% 0% / 0);
    --shadow: 0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 1px 2px -1px hsl(0 0% 0% / 0);
    --shadow-md:
      0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 2px 4px -1px hsl(0 0% 0% / 0);
    --shadow-lg:
      0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 4px 6px -1px hsl(0 0% 0% / 0);
    --shadow-xl:
      0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 8px 10px -1px hsl(0 0% 0% / 0);
    --shadow-2xl: 0px 1px 0px 0px hsl(0 0% 0% / 0);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 300 0% 3.55%;
    --foreground: 300 0% 98.68%;
    --card: 300 0% 9.5%;
    --card-foreground: 300 0% 98.68%;
    --popover: 300 0% 15.03%;
    --popover-foreground: 300 0% 98.68%;
    --primary: 0 0% 45.61%;
    --primary-foreground: 300 0% 98.68%;
    --secondary: 300 0% 15.03%;
    --secondary-foreground: 300 0% 98.68%;
    --muted: 300 0% 15.03%;
    --muted-foreground: 0 0% 63.26%;
    --accent: 0 0% 24.94%;
    --accent-foreground: 300 0% 98.68%;
    --destructive: 358.77 99.41% 69.3%;
    --destructive-foreground: 300 0% 15.03%;
    --border: 0 0% 21.89%;
    --input: 330 0% 32.31%;
    --ring: 0 0% 45.61%;
    --chart-1: 0 0% 45.61%;
    --chart-2: 0 0% 45.61%;
    --chart-3: 0 0% 45.61%;
    --chart-4: 0 0% 45.61%;
    --chart-5: 0 0% 45.61%;
    --radius: 0rem;
    --sidebar: 0 0% 8.61%;
    --sidebar-foreground: 300 0% 98.68%;
    --sidebar-primary: 300 0% 98.68%;
    --sidebar-primary-foreground: 0 0% 8.61%;
    --sidebar-accent: 300 0% 15.03%;
    --sidebar-accent-foreground: 300 0% 98.68%;
    --sidebar-border: 300 50% 100%;
    --sidebar-ring: 330 0% 32.31%;
    --font-sans: Geist Mono, monospace;
    --font-serif: Geist Mono, monospace;
    --font-mono: Geist Mono, monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0;
    --shadow-blur: 0px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 1px 0px 0px hsl(0 0% 0% / 0);
    --shadow-xs: 0px 1px 0px 0px hsl(0 0% 0% / 0);
    --shadow-sm:
      0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 1px 2px -1px hsl(0 0% 0% / 0);
    --shadow: 0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 1px 2px -1px hsl(0 0% 0% / 0);
    --shadow-md:
      0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 2px 4px -1px hsl(0 0% 0% / 0);
    --shadow-lg:
      0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 4px 6px -1px hsl(0 0% 0% / 0);
    --shadow-xl:
      0px 1px 0px 0px hsl(0 0% 0% / 0), 0px 8px 10px -1px hsl(0 0% 0% / 0);
    --shadow-2xl: 0px 1px 0px 0px hsl(0 0% 0% / 0);
  }

}
